import { currentLocale, type AppLocale } from '@/i18n';
import type { LegalBlock } from '@/components/settings/LegalScreen';
import privacyEn from '@/constants/legal/privacy.en';
import privacyHe from '@/constants/legal/privacy.he';
import privacyRo from '@/constants/legal/privacy.ro';
import termsEn from '@/constants/legal/terms.en';
import termsHe from '@/constants/legal/terms.he';
import termsRo from '@/constants/legal/terms.ro';

/**
 * Keep in sync with the "Last updated" line in website/privacy.txt and terms.txt.
 * The texts under constants/legal are generated by website/build-legal.mjs.
 */
export const LEGAL_LAST_UPDATED_ISO = '2026-11-23';

/** Locales without a translation fall back to English. */
const PRIVACY: Partial<Record<AppLocale, string>> = { en: privacyEn, he: privacyHe, ro: privacyRo };
const TERMS: Partial<Record<AppLocale, string>> = { en: termsEn, he: termsHe, ro: termsRo };

function parse(text: string): LegalBlock[] {
  const blocks: LegalBlock[] = [];
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (!line) continue;
    if (line.startsWith('### ')) blocks.push({ type: 'subheading', text: line.slice(4) });
    else if (line.startsWith('## ')) blocks.push({ type: 'heading', text: line.slice(3) });
    else if (line.startsWith('- ')) blocks.push({ type: 'bullet', text: line.slice(2) });
    else blocks.push({ type: 'body', text: line });
  }
  return blocks;
}

export function privacyPolicyBlocks(): LegalBlock[] {
  return parse(PRIVACY[currentLocale] ?? privacyEn);
}

export function termsOfServiceBlocks(): LegalBlock[] {
  return parse(TERMS[currentLocale] ?? termsEn);
}
